<?php

namespace App\Http\Controllers\Api\Accounting;

use App\Http\Controllers\Api\ResourceController;
use App\Models\Voucher;
use App\Support\Finance;
use App\Support\Numbering;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Http\Request;

/**
 * Receipt (قبض) and payment (صرف) vouchers. Vouchers generated by other
 * documents (contracts, invoices, expenses, payroll) are read-only here —
 * they are managed from their source screen.
 */
class VoucherController extends ResourceController
{
    protected string $model = Voucher::class;

    protected array $search = ['number', 'party_name', 'description', 'reference'];

    protected array $filters = ['type', 'category', 'cash_account_id', 'method', 'party_type'];

    protected array $with = ['cashAccount:id,name,name_en', 'creator:id,name'];

    protected array $sortable = ['id', 'date', 'amount'];

    protected ?string $dateColumn = 'date';

    protected string $order = 'date';

    protected string $label = 'سند';

    public const CATEGORIES = ['tuition', 'service', 'expense', 'salary', 'advance', 'purchase', 'other'];

    protected function rules(Request $request, ?Model $record): array
    {
        $req = $record ? 'sometimes' : 'required';

        return [
            'type'            => [$req, 'in:receipt,payment'],
            'date'            => [$req, 'date'],
            'amount'          => [$req, 'numeric', 'min:0.001'],
            'cash_account_id' => ['nullable', 'integer', $this->owned('cash_accounts')],
            'method'          => ['nullable', 'in:cash,bank,card,cheque'],
            'reference'       => ['nullable', 'string', 'max:120'],
            'category'        => ['nullable', 'in:'.implode(',', self::CATEGORIES)],
            'party_type'      => ['nullable', 'in:guardian,customer,supplier,employee,other'],
            'party_name'      => ['nullable', 'string', 'max:255'],
            'party_name_en'   => ['nullable', 'string', 'max:255'],
            'description'     => ['nullable', 'string', 'max:255'],
            'description_en'  => ['nullable', 'string', 'max:255'],
        ];
    }

    public function index(Request $request)
    {
        $res = parent::index($request);
        $q = $this->baseQuery($request);
        $this->applyListFilters($q, $request);
        $sums = (clone $q)->selectRaw("SUM(CASE WHEN type='receipt' THEN amount ELSE 0 END) r, SUM(CASE WHEN type='payment' THEN amount ELSE 0 END) p")->first();
        $data = $res->getData(true);
        $data['sums'] = ['receipts' => round((float) $sums->r, 3), 'payments' => round((float) $sums->p, 3)];

        return response()->json($data);
    }

    protected function prepare(array $data, Request $request, ?Model $record): array
    {
        if ($record && $record->source_type) {
            abort(response()->json(['message' => 'هذا السند مرتبط بمستند آخر ويُدار من شاشته.'], 422));
        }
        if (! $record) {
            $data['number'] = Numbering::next(Voucher::class, $data['type'] === 'receipt' ? 'RC-' : 'PV-', 6, 'number', ['type' => $data['type']]);
            $data['created_by'] = $request->user()->id;
            $data['category'] = $data['category'] ?? 'other';
            $data['cash_account_id'] = $data['cash_account_id'] ?? \App\Models\CashAccount::where('type', 'cash')->value('id');
        }
        if (isset($data['amount'])) {
            $data['amount'] = Finance::r((float) $data['amount']);
        }

        return $data;
    }

    protected function cannotDelete(Model $record): ?string
    {
        return $record->source_type ? 'هذا السند مرتبط بمستند (عقد/فاتورة/مصروف/رواتب) — احذفه من شاشة المستند.' : null;
    }
}
